package com.examination.notificationservice.controller;
import com.examination.notificationservice.model.Notification; import com.examination.notificationservice.service.NotificationService; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/notifications") public class NotificationController { private final NotificationService service; public NotificationController(NotificationService s){service=s;} @GetMapping public List<Notification> all(){return service.all();} @GetMapping("/{id}") public Notification get(@PathVariable Long id){return service.byId(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Notification create(@RequestBody Notification x){return service.save(x);} }
